.campaign-section-heading{display:flex;align-items:flex-start;gap:12px;margin-bottom:24px}.campaign-section-heading h3{margin:0;font-size:20px;color:#102a43}.campaign-section-heading p{margin:4px 0 0;color:#6b7c93}.section-number{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#e8f7f5;color:#087f78;font-weight:800;font-size:12px}.task-builder{border:1px solid #dbe5ef;border-radius:14px;padding:18px;margin-bottom:14px;background:#fbfdff}.task-builder-top{display:flex;align-items:center;margin-bottom:16px;color:#16324f}.task-number{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#16324f;color:#fff;font-size:12px;margin-right:8px}.task-builder label{font-size:13px;font-weight:700;color:#425466}.task-mode{font-size:12px;color:#60758a;padding-top:4px}.task-mode i{color:#0b8f84}.empty-task-state{display:flex;align-items:center;flex-direction:column;gap:6px;padding:34px;color:#708399;border:1px dashed #cbd8e5;border-radius:14px}.empty-task-state i{font-size:28px;color:#0b8f84}.allocation-note{display:flex;gap:10px;padding:14px;border-radius:10px;background:#f0f8ff;color:#3e5b76;font-size:13px}.allocation-note i{color:#147d9a}.sticky-panel{position:sticky;top:20px}.publish-footnote{font-size:12px;color:#718096;margin:16px 0 0;line-height:1.5}.publish-footnote i{margin-right:4px;color:#0b8f84}
