<script>
(function () { var list=document.getElementById('task-list'), empty=document.getElementById('empty-tasks'), nextIndex={{ count($taskRows) }}, types='<option value="website_visit">Visit website</option><option value="follow_x">Follow on X</option><option value="join_telegram">Join Telegram</option><option value="join_discord">Join Discord</option><option value="follow_founder">Follow founder</option><option value="custom">Custom task</option>';
  function refresh(row){var type=row.querySelector('.task-type').value, mode=(type==='website_visit'||type==='join_telegram')?'click_claim':'admin_approval';row.querySelector('.completion-mode').value=mode;row.querySelector('.task-mode span').textContent=type==='join_telegram'?'Open Telegram and claim the reward when you return. Membership is not checked.':(mode==='click_claim'?'Click-and-claim: user opens the link, then can claim immediately.':'Admin review: user submits proof after opening the link.');}
  function renumber(){Array.prototype.forEach.call(list.querySelectorAll('[data-task-row]'),function(row,pos){row.querySelector('.task-number').textContent=pos+1;});empty.style.display=list.querySelector('[data-task-row]')?'none':'flex';}
  function bind(row){row.querySelector('.remove-task').addEventListener('click',function(){row.remove();renumber();});row.querySelector('.task-type').addEventListener('change',function(){refresh(row);});refresh(row);}
  function addTask(){var i=nextIndex++,row=document.createElement('div');row.className='task-builder';row.setAttribute('data-task-row','');row.innerHTML='<div class="task-builder-top"><span class="task-number">1</span><strong>Task</strong><button class="btn btn-sm btn-link text-danger ml-auto remove-task" type="button">Remove</button></div><input type="hidden" name="tasks['+i+'][id]" value=""><div class="row"><div class="col-md-4"><div class="form-group"><label>Task type</label><select class="form-control task-type" name="tasks['+i+'][task_type]">'+types+'</select></div></div><div class="col-md-8"><div class="form-group"><label>Task title</label><input class="form-control" name="tasks['+i+'][title]" required maxlength="180" placeholder="Complete partner task"></div></div></div><div class="row"><div class="col-md-8"><div class="form-group"><label>Task link</label><input class="form-control" type="url" name="tasks['+i+'][target_url]" required maxlength="2000" placeholder="https://..."></div></div><div class="col-md-2"><div class="form-group"><label>Reward</label><input class="form-control" type="number" step="0.0001" min="0.0001" name="tasks['+i+'][reward_amount]" required placeholder="100"></div></div><div class="col-md-2"><div class="form-group"><label>User limit</label><input class="form-control" type="number" min="1" name="tasks['+i+'][participant_limit]" placeholder="Any"></div></div></div><div class="form-group mb-2"><label>Instructions for users</label><textarea class="form-control" name="tasks['+i+'][instructions]" rows="2" maxlength="3000" placeholder="Tell users exactly what to do and what proof to submit."></textarea></div><input type="hidden" class="completion-mode" name="tasks['+i+'][completion_mode]" value="click_claim"><div class="task-mode"><i class="fa-solid fa-circle-info"></i> <span></span></div>';list.appendChild(row);bind(row);renumber();}
  Array.prototype.forEach.call(list.querySelectorAll('[data-task-row]'),bind);document.getElementById('add-task').addEventListener('click',addTask);renumber();
}());
</script>
